-- P18 Marketing Autopilot: consent-aware, human-approved and provider-neutral orchestration.
create table public.marketing_consents(id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,purpose text not null check(purpose in('SOCIAL_PUBLISHING','MARKETING_ANALYTICS','PERSONAL_DATA_CONTENT')),decision text not null check(decision in('GRANTED','WITHDRAWN')),policy_version text not null,evidence_hash text not null check(evidence_hash~'^[0-9a-f]{64}$'),decided_by uuid not null references auth.users(id),decided_at timestamptz not null default clock_timestamp(),unique(organization_id,purpose,decided_at));
create table public.brand_kits(id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null unique references public.organizations(id)on delete restrict,status text not null default'DRAFT'check(status in('DRAFT','READY','SUSPENDED')),current_version_id uuid,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),row_version integer not null default 1 check(row_version>0));
create table public.brand_kit_versions(id uuid primary key default extensions.gen_random_uuid(),brand_kit_id uuid not null references public.brand_kits(id)on delete restrict,version integer not null check(version>0),payload jsonb not null check(jsonb_typeof(payload)='object'and payload?&array['legal_name','trade_name','primary_colors','tone','languages','primary_cta','tracked_url','required_mentions','forbidden_terms','approved_hashtags']),claims jsonb not null default'[]'check(jsonb_typeof(claims)='array'),certifications jsonb not null default'[]'check(jsonb_typeof(certifications)='array'),content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),change_reason text not null check(length(btrim(change_reason))between 3 and 500),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),unique(brand_kit_id,version),unique(brand_kit_id,id));
alter table public.brand_kits add constraint brand_kits_current_fk foreign key(id,current_version_id)references public.brand_kit_versions(brand_kit_id,id)on delete restrict;
create table public.marketing_templates(id uuid primary key default extensions.gen_random_uuid(),template_key text not null unique check(template_key in('PROBLEM_SOLUTION','EXPERT_TIP','PROVIDER_INTRO','BEFORE_AFTER','SERVICE_OF_MONTH','SUCCESS_CASE')),status text not null default'DRAFT'check(status in('DRAFT','ACTIVE','RETIRED')),current_version_id uuid,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp());
create table public.marketing_template_versions(id uuid primary key default extensions.gen_random_uuid(),template_id uuid not null references public.marketing_templates(id)on delete restrict,version integer not null check(version>0),structure jsonb not null check(jsonb_typeof(structure)='object'and structure?&array['hook','body','target_characters','required_media','allowed_ctas','forbidden_claims','translation_rules','repetition_rules']),frequency_max_weekly integer not null check(frequency_max_weekly between 1 and 50),content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),unique(template_id,version),unique(template_id,id));
alter table public.marketing_templates add constraint marketing_templates_current_fk foreign key(id,current_version_id)references public.marketing_template_versions(template_id,id)on delete restrict;
create table public.social_connections(id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,provider text not null check(provider in('LINKEDIN','META')),status text not null check(status in('ACTIVE','REVOKED','ERROR')),scopes text[]not null,credential_reference text not null check(credential_reference!~*'(token|secret|password)='),connected_by uuid not null references auth.users(id),connected_at timestamptz not null default clock_timestamp(),revoked_at timestamptz,unique(organization_id,provider),check((status='REVOKED')=(revoked_at is not null)));
create table public.marketing_campaigns(id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,brand_kit_version_id uuid not null references public.brand_kit_versions(id)on delete restrict,mode text not null default'ASSISTED'check(mode in('MANUAL','ASSISTED','AUTOPILOT')),title_fr text not null,title_ar text not null,status text not null default'DRAFT'check(status in('DRAFT','GENERATED','VALIDATED_BY_RULES','APPROVED','SCHEDULED','PUBLISHED','FAILED','SKIPPED','CANCELLED')),frequency_max_weekly integer not null default 8 check(frequency_max_weekly between 1 and 50),risk_threshold integer not null default 20 check(risk_threshold between 0 and 100),audience_snapshot jsonb not null check(jsonb_typeof(audience_snapshot)='object'),source_snapshot jsonb not null check(jsonb_typeof(source_snapshot)='object'),approved_by uuid references auth.users(id),approved_at timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),row_version integer not null default 1 check(row_version>0),check((status in('APPROVED','SCHEDULED','PUBLISHED'))=(approved_by is not null and approved_at is not null)));
create table public.marketing_content(id uuid primary key default extensions.gen_random_uuid(),campaign_id uuid not null references public.marketing_campaigns(id)on delete restrict,channel text not null check(channel in('LINKEDIN','FACEBOOK','INSTAGRAM','REEL')),template_version_id uuid not null references public.marketing_template_versions(id)on delete restrict,service_id uuid references public.catalog_services(id)on delete restrict,library_id uuid references public.catalog_libraries(id)on delete restrict,current_version_id uuid,created_at timestamptz not null default clock_timestamp(),unique(campaign_id,channel,template_version_id));
create table public.marketing_content_versions(id uuid primary key default extensions.gen_random_uuid(),content_id uuid not null references public.marketing_content(id)on delete restrict,version integer not null check(version>0),language text not null check(language in('FR','AR')),title_internal text not null,hook text not null,body text not null,cta text not null,hashtags text[]not null,landing_url text not null check(landing_url~'^https://'),claims_used jsonb not null default'[]'check(jsonb_typeof(claims_used)='array'),compliance_checks jsonb not null check(jsonb_typeof(compliance_checks)='object'and compliance_checks?&array['source','brand','claims','privacy','certification','promotion','duplicate']),risk_score integer not null check(risk_score between 0 and 100),status text not null check(status in('GENERATED','BLOCKED','VALIDATED_BY_RULES','APPROVED','EXPIRED')),expires_at timestamptz,content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),unique(content_id,version,language),unique(content_id,id));
alter table public.marketing_content add constraint marketing_content_current_fk foreign key(id,current_version_id)references public.marketing_content_versions(content_id,id)on delete restrict;
create table public.marketing_content_sources(id uuid primary key default extensions.gen_random_uuid(),content_version_id uuid not null references public.marketing_content_versions(id)on delete restrict,source_type text not null check(source_type in('CATALOG','ANOMALY_AGGREGATE','RECOMMENDATION','OPPORTUNITY','PROFILE','BADGE','OFFER','BRAND_KIT')),source_id text not null,source_hash text not null check(source_hash~'^[0-9a-f]{64}$'),aggregate_size integer,created_at timestamptz not null default clock_timestamp(),check(source_type<>'ANOMALY_AGGREGATE'or aggregate_size>=10));
create table public.marketing_calendar_items(id uuid primary key default extensions.gen_random_uuid(),campaign_id uuid not null references public.marketing_campaigns(id)on delete restrict,content_version_id uuid not null references public.marketing_content_versions(id)on delete restrict,social_connection_id uuid not null references public.social_connections(id)on delete restrict,scheduled_at timestamptz not null,status text not null check(status in('SCHEDULED','PUBLISHED','FAILED','SKIPPED','CANCELLED')),created_at timestamptz not null default clock_timestamp(),unique(content_version_id,social_connection_id,scheduled_at));
create table public.marketing_exceptions(id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,campaign_id uuid not null references public.marketing_campaigns(id)on delete restrict,content_version_id uuid references public.marketing_content_versions(id)on delete restrict,exception_type text not null,severity text not null check(severity in('WARNING','BLOCKING')),reason text not null,automatic_resolution_possible boolean not null default false,status text not null default'OPEN'check(status in('OPEN','RESOLVED','DISMISSED')),assigned_to uuid references auth.users(id),resolution text,created_at timestamptz not null default clock_timestamp());
create table public.social_publication_jobs(id uuid primary key default extensions.gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,calendar_item_id uuid not null unique references public.marketing_calendar_items(id)on delete restrict,provider text not null,status text not null default'QUEUED'check(status in('QUEUED','CLAIMED','PUBLISHED','FAILED','SKIPPED')),attempt_count integer not null default 0 check(attempt_count between 0 and 20),idempotency_key text not null,available_at timestamptz not null,created_at timestamptz not null default clock_timestamp(),unique(provider,idempotency_key));
create table public.social_publication_results(id bigint generated always as identity primary key,job_id uuid not null references public.social_publication_jobs(id)on delete restrict,attempt integer not null check(attempt>0),outcome text not null check(outcome in('PUBLISHED','RETRYABLE_FAILURE','PERMANENT_FAILURE','SKIPPED_CONSENT')),provider_publication_id text,error_code text,occurred_at timestamptz not null default clock_timestamp(),unique(job_id,attempt),check((outcome='PUBLISHED')=(provider_publication_id is not null)));
create table public.marketing_attribution_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id)on delete restrict,campaign_id uuid not null references public.marketing_campaigns(id)on delete restrict,content_id uuid references public.marketing_content(id)on delete restrict,event_type text not null check(event_type in('CONTENT_VIEWED','CTA_CLICKED','LANDING_VIEWED','REGISTRATION_STARTED','DIAGNOSTIC_STARTED','OPPORTUNITY_CREATED','RFQ_STARTED','CONTRACT_SIGNED')),source text not null,medium text not null,visitor_hash text not null check(visitor_hash~'^[0-9a-f]{64}$'),economic_value_minor bigint,occurred_at timestamptz not null,metadata jsonb not null default'{}'check(jsonb_typeof(metadata)='object'),check(economic_value_minor is null or economic_value_minor>=0));
create table public.marketing_metric_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id)on delete restrict,campaign_id uuid not null references public.marketing_campaigns(id)on delete restrict,metric text not null check(metric in('GENERATED','PUBLISHED','FAILED','IMPRESSION','VIEW','CLICK','LEAD','DIAGNOSTIC','OPPORTUNITY','RFQ','CONTRACT','ATTRIBUTED_VALUE','MARKETING_COST')),quantity bigint not null check(quantity>0),value_minor bigint,currency char(3),source_event_id text not null,occurred_at timestamptz not null,created_at timestamptz not null default clock_timestamp(),unique(campaign_id,metric,source_event_id),check((value_minor is null)=(currency is null)),check((metric in('ATTRIBUTED_VALUE','MARKETING_COST'))=(value_minor is not null)),check(value_minor is null or value_minor>=0));

create function private.marketing_manage_access(p_org uuid,p_actor uuid default auth.uid())returns boolean language sql stable security definer set search_path=pg_catalog,private as $$select private.has_org_role(p_org,array['CLIENT_OWNER','CLIENT_ADMIN','PROVIDER_OWNER','PROVIDER_MANAGER','PROVIDER_SALES','FRANCHISE_OWNER','FRANCHISE_MANAGER'],p_actor)or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN'],p_actor)$$;
create function private.marketing_consent_active(p_org uuid,p_purpose text)returns boolean language sql stable security definer set search_path=pg_catalog,public as $$select coalesce((select decision='GRANTED'from public.marketing_consents where organization_id=p_org and purpose=p_purpose order by decided_at desc,id desc limit 1),false)$$;
create function private.prevent_marketing_history_change()returns trigger language plpgsql set search_path=pg_catalog as $$begin raise exception'MARKETING_HISTORY_IMMUTABLE'using errcode='55000';end$$;

create function public.record_marketing_consent(p_organization_id uuid,p_purpose text,p_decision text,p_policy_version text,p_evidence_hash text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();h text;cached jsonb;r jsonb;c uuid;begin if a is null or not private.marketing_manage_access(p_organization_id,a)then raise exception'MARKETING_CONSENT_DENIED'using errcode='42501';end if;if p_purpose not in('SOCIAL_PUBLISHING','MARKETING_ANALYTICS','PERSONAL_DATA_CONTENT')or p_decision not in('GRANTED','WITHDRAWN')or length(btrim(coalesce(p_policy_version,'')))<1 or p_evidence_hash!~'^[0-9a-f]{64}$'then raise exception'INVALID_MARKETING_CONSENT'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('org',p_organization_id,'purpose',p_purpose,'decision',p_decision,'policy',p_policy_version,'evidence',p_evidence_hash));cached:=private.begin_contract_command(p_organization_id,'marketing.consent.'||p_purpose,p_idempotency_key,h,a);if cached is not null then return cached;end if;insert into public.marketing_consents(organization_id,purpose,decision,policy_version,evidence_hash,decided_by)values(p_organization_id,p_purpose,p_decision,p_policy_version,p_evidence_hash,a)returning id into c;if p_purpose='SOCIAL_PUBLISHING'and p_decision='WITHDRAWN'then update public.social_publication_jobs set status='SKIPPED'where organization_id=p_organization_id and status='QUEUED';update public.marketing_calendar_items i set status='SKIPPED'from public.marketing_campaigns m where i.campaign_id=m.id and m.organization_id=p_organization_id and i.status='SCHEDULED';end if;r:=jsonb_build_object('outcome','MARKETING_CONSENT_'||p_decision,'consent_id',c,'purpose',p_purpose);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','marketing.consent.'||lower(p_decision),'marketing_consent',c::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'marketing_consent',c::text,'MarketingConsent'||initcap(lower(p_decision))||'V1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_organization_id,'marketing.consent.'||p_purpose,p_idempotency_key,r);return r;end$$;

create function public.create_marketing_campaign(p_organization_id uuid,p_brand_kit_version_id uuid,p_mode text,p_title_fr text,p_title_ar text,p_frequency_max_weekly integer,p_risk_threshold integer,p_audience_snapshot jsonb,p_source_snapshot jsonb,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();b public.brand_kits%rowtype;h text;cached jsonb;r jsonb;c uuid;begin select k.*into b from public.brand_kits k join public.brand_kit_versions v on v.brand_kit_id=k.id where v.id=p_brand_kit_version_id;if a is null or not found or b.organization_id<>p_organization_id or not private.marketing_manage_access(p_organization_id,a)then raise exception'MARKETING_CAMPAIGN_DENIED'using errcode='42501';end if;if b.status<>'READY'or p_mode not in('MANUAL','ASSISTED','AUTOPILOT')or(p_mode='AUTOPILOT'and(not private.marketing_consent_active(p_organization_id,'SOCIAL_PUBLISHING')or not exists(select 1 from public.social_connections where organization_id=p_organization_id and status='ACTIVE')))or length(btrim(p_title_fr))<3 or length(btrim(p_title_ar))<2 or p_frequency_max_weekly not between 1 and 50 or p_risk_threshold not between 0 and 100 or jsonb_typeof(p_audience_snapshot)<>'object'or jsonb_typeof(p_source_snapshot)<>'object'then raise exception'INVALID_MARKETING_CAMPAIGN'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('org',p_organization_id,'brand',p_brand_kit_version_id,'mode',p_mode,'fr',p_title_fr,'ar',p_title_ar,'frequency',p_frequency_max_weekly,'risk',p_risk_threshold,'audience',p_audience_snapshot,'source',p_source_snapshot));cached:=private.begin_contract_command(p_organization_id,'marketing.campaign.create',p_idempotency_key,h,a);if cached is not null then return cached;end if;insert into public.marketing_campaigns(organization_id,brand_kit_version_id,mode,title_fr,title_ar,frequency_max_weekly,risk_threshold,audience_snapshot,source_snapshot,created_by)values(p_organization_id,p_brand_kit_version_id,p_mode,p_title_fr,p_title_ar,p_frequency_max_weekly,p_risk_threshold,p_audience_snapshot,p_source_snapshot,a)returning id into c;r:=jsonb_build_object('outcome','MARKETING_CAMPAIGN_CREATED','campaign_id',c,'mode',p_mode);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','marketing.campaign.created','marketing_campaign',c::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'marketing_campaign',c::text,'MarketingCampaignCreatedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_organization_id,'marketing.campaign.create',p_idempotency_key,r);return r;end$$;

create function public.approve_marketing_campaign(p_campaign_id uuid,p_expected_row_version integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();c public.marketing_campaigns%rowtype;h text;cached jsonb;r jsonb;begin select*into c from public.marketing_campaigns where id=p_campaign_id;if a is null or not found or not private.marketing_manage_access(c.organization_id,a)then raise exception'MARKETING_APPROVAL_DENIED'using errcode='42501';end if;if c.status<>'VALIDATED_BY_RULES'or c.row_version<>p_expected_row_version or exists(select 1 from public.marketing_exceptions where campaign_id=c.id and severity='BLOCKING'and status='OPEN')or not exists(select 1 from public.marketing_content x join public.marketing_content_versions v on v.id=x.current_version_id where x.campaign_id=c.id and v.status='VALIDATED_BY_RULES')then raise exception'MARKETING_CAMPAIGN_NOT_APPROVABLE'using errcode='55000';end if;h:=private.canonical_request_hash(jsonb_build_object('campaign',c.id,'expected',p_expected_row_version));cached:=private.begin_contract_command(c.organization_id,'marketing.campaign.approve.'||c.id,p_idempotency_key,h,a);if cached is not null then return cached;end if;update public.marketing_campaigns set status='APPROVED',approved_by=a,approved_at=clock_timestamp(),row_version=row_version+1 where id=c.id and row_version=p_expected_row_version;if not found then raise exception'STALE_MARKETING_CAMPAIGN'using errcode='40001';end if;update public.marketing_content_versions v set status='APPROVED'from public.marketing_content x where x.current_version_id=v.id and x.campaign_id=c.id and v.status='VALIDATED_BY_RULES';r:=jsonb_build_object('outcome','MARKETING_CAMPAIGN_APPROVED','campaign_id',c.id,'approved_by',a);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(c.organization_id,a,'USER','marketing.campaign.approved','marketing_campaign',c.id::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(c.organization_id,'marketing_campaign',c.id::text,'MarketingCampaignApprovedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(c.organization_id,'marketing.campaign.approve.'||c.id,p_idempotency_key,r);return r;end$$;

create function public.schedule_marketing_campaign(p_campaign_id uuid,p_items jsonb,p_expected_row_version integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();c public.marketing_campaigns%rowtype;h text;cached jsonb;r jsonb;x jsonb;v public.marketing_content_versions%rowtype;conn public.social_connections%rowtype;i uuid;n integer:=0;week_count integer;begin select*into c from public.marketing_campaigns where id=p_campaign_id for update;if a is null or not found or not private.marketing_manage_access(c.organization_id,a)then raise exception'MARKETING_SCHEDULE_DENIED'using errcode='42501';end if;if c.status<>'APPROVED'or c.row_version<>p_expected_row_version or not private.marketing_consent_active(c.organization_id,'SOCIAL_PUBLISHING')or jsonb_typeof(p_items)<>'array'or jsonb_array_length(p_items)not between 1 and 100 then raise exception'MARKETING_CAMPAIGN_NOT_SCHEDULABLE'using errcode='55000';end if;h:=private.canonical_request_hash(jsonb_build_object('campaign',c.id,'items',p_items,'expected',p_expected_row_version));cached:=private.begin_contract_command(c.organization_id,'marketing.campaign.schedule.'||c.id,p_idempotency_key,h,a);if cached is not null then return cached;end if;for x in select value from jsonb_array_elements(p_items)loop select v.*into v from public.marketing_content_versions v join public.marketing_content mc on mc.id=v.content_id where v.id=(x->>'content_version_id')::uuid and mc.campaign_id=c.id;select*into conn from public.social_connections where id=(x->>'social_connection_id')::uuid and organization_id=c.organization_id and status='ACTIVE';if v.id is null or conn.id is null or v.status<>'APPROVED'or v.risk_score>c.risk_threshold or v.expires_at is not null and v.expires_at<=(x->>'scheduled_at')::timestamptz or exists(select 1 from jsonb_each_text(v.compliance_checks)q where q.value<>'PASS')then raise exception'MARKETING_CONTENT_BLOCKED'using errcode='23514';end if;select count(*)into week_count from public.marketing_calendar_items ci join public.marketing_campaigns mc on mc.id=ci.campaign_id where mc.organization_id=c.organization_id and ci.scheduled_at>=((x->>'scheduled_at')::timestamptz-interval'7 days')and ci.scheduled_at<=((x->>'scheduled_at')::timestamptz+interval'7 days')and ci.status in('SCHEDULED','PUBLISHED');if week_count>=c.frequency_max_weekly then raise exception'MARKETING_FREQUENCY_LIMIT'using errcode='23514';end if;insert into public.marketing_calendar_items(campaign_id,content_version_id,social_connection_id,scheduled_at,status)values(c.id,v.id,conn.id,(x->>'scheduled_at')::timestamptz,'SCHEDULED')returning id into i;insert into public.social_publication_jobs(organization_id,calendar_item_id,provider,status,idempotency_key,available_at)values(c.organization_id,i,conn.provider,'QUEUED',p_idempotency_key||':'||n,(x->>'scheduled_at')::timestamptz);insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(c.organization_id,'marketing_calendar_item',i::text,'SocialPublicationScheduledV1',p_correlation_id,jsonb_build_object('calendar_item_id',i,'content_version_id',v.id,'provider',conn.provider),p_idempotency_key||':'||n);n:=n+1;end loop;update public.marketing_campaigns set status='SCHEDULED',row_version=row_version+1 where id=c.id;r:=jsonb_build_object('outcome','MARKETING_CAMPAIGN_SCHEDULED','campaign_id',c.id,'scheduled_count',n);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(c.organization_id,a,'USER','marketing.campaign.scheduled','marketing_campaign',c.id::text,p_correlation_id,r,repeat('0',64));perform private.finish_contract_command(c.organization_id,'marketing.campaign.schedule.'||c.id,p_idempotency_key,r);return r;exception when invalid_text_representation then raise exception'INVALID_MARKETING_SCHEDULE'using errcode='22023';end$$;

create function public.record_marketing_metric(p_campaign_id uuid,p_metric text,p_quantity bigint,p_value_minor bigint,p_currency text,p_source_event_id text,p_occurred_at timestamptz,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();c public.marketing_campaigns%rowtype;h text;cached jsonb;r jsonb;e bigint;begin select*into c from public.marketing_campaigns where id=p_campaign_id;if a is null or not found or not private.marketing_manage_access(c.organization_id,a)then raise exception'MARKETING_METRIC_DENIED'using errcode='42501';end if;if p_metric not in('GENERATED','PUBLISHED','FAILED','IMPRESSION','VIEW','CLICK','LEAD','DIAGNOSTIC','OPPORTUNITY','RFQ','CONTRACT','ATTRIBUTED_VALUE','MARKETING_COST')or p_quantity<=0 or length(btrim(p_source_event_id))<3 or p_occurred_at>clock_timestamp()+interval'5 minutes'or((p_value_minor is null)<>(p_currency is null))or(p_currency is not null and p_currency!~'^[A-Z]{3}$')then raise exception'INVALID_MARKETING_METRIC'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('campaign',c.id,'metric',p_metric,'quantity',p_quantity,'value',p_value_minor,'currency',p_currency,'source',p_source_event_id,'occurred',p_occurred_at));cached:=private.begin_contract_command(c.organization_id,'marketing.metric.'||c.id,p_idempotency_key,h,a);if cached is not null then return cached;end if;insert into public.marketing_metric_events(organization_id,campaign_id,metric,quantity,value_minor,currency,source_event_id,occurred_at)values(c.organization_id,c.id,p_metric,p_quantity,p_value_minor,p_currency,p_source_event_id,p_occurred_at)returning id into e;r:=jsonb_build_object('outcome','MARKETING_METRIC_RECORDED','metric_event_id',e,'campaign_id',c.id);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(c.organization_id,a,'USER','marketing.metric.recorded','marketing_metric_event',e::text,p_correlation_id,jsonb_build_object('metric',p_metric,'quantity',p_quantity),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(c.organization_id,'marketing_campaign',c.id::text,'MarketingMetricRecordedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(c.organization_id,'marketing.metric.'||c.id,p_idempotency_key,r);return r;end$$;

create view public.marketing_campaign_performance with(security_invoker=true)as with contents as(select campaign_id,count(*)::bigint generated from public.marketing_content group by campaign_id),publications as(select campaign_id,count(*)filter(where status='PUBLISHED')::bigint published,count(*)filter(where status='FAILED')::bigint failed from public.marketing_calendar_items group by campaign_id),metrics as(select campaign_id,coalesce(sum(quantity)filter(where metric='IMPRESSION'),0)::bigint impressions,coalesce(sum(quantity)filter(where metric='CLICK'),0)::bigint clicks,coalesce(sum(quantity)filter(where metric='LEAD'),0)::bigint leads,coalesce(sum(quantity)filter(where metric='DIAGNOSTIC'),0)::bigint diagnostics,coalesce(sum(quantity)filter(where metric='OPPORTUNITY'),0)::bigint opportunities,coalesce(sum(quantity)filter(where metric='RFQ'),0)::bigint rfqs,coalesce(sum(quantity)filter(where metric='CONTRACT'),0)::bigint contracts,coalesce(sum(value_minor)filter(where metric='ATTRIBUTED_VALUE'),0)::bigint attributed_value_minor,coalesce(sum(value_minor)filter(where metric='MARKETING_COST'),0)::bigint marketing_cost_minor,coalesce(sum(quantity)filter(where metric='FAILED'),0)::bigint failed_events from public.marketing_metric_events group by campaign_id)select c.organization_id,c.id campaign_id,coalesce(x.generated,0)::bigint contents_generated,coalesce(p.published,0)::bigint contents_published,coalesce(p.failed,0)::bigint publications_failed,coalesce(m.impressions,0)::bigint impressions,coalesce(m.clicks,0)::bigint clicks,coalesce(m.leads,0)::bigint leads,coalesce(m.diagnostics,0)::bigint diagnostics,coalesce(m.opportunities,0)::bigint opportunities,coalesce(m.rfqs,0)::bigint rfqs,coalesce(m.contracts,0)::bigint contracts,coalesce(m.attributed_value_minor,0)::bigint attributed_value_minor,coalesce(m.marketing_cost_minor,0)::bigint marketing_cost_minor,case when coalesce(m.failed_events,0)>0 then'PAUSE_CAMPAIGN'when coalesce(m.clicks,0)=0 and coalesce(m.impressions,0)>100 then'CHANGE_TEMPLATE'when coalesce(m.clicks,0)>20 then'INCREASE_FREQUENCY'else'KEEP'end feedback from public.marketing_campaigns c left join contents x on x.campaign_id=c.id left join publications p on p.campaign_id=c.id left join metrics m on m.campaign_id=c.id;

do $$declare t text;begin foreach t in array array['marketing_consents','brand_kits','brand_kit_versions','marketing_templates','marketing_template_versions','social_connections','marketing_campaigns','marketing_content','marketing_content_versions','marketing_content_sources','marketing_calendar_items','marketing_exceptions','social_publication_jobs','social_publication_results','marketing_attribution_events','marketing_metric_events']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('create policy %I on public.%I for select to authenticated using (%s)',t||'_scoped_read',t,case when t in('marketing_templates','marketing_template_versions')then'private.has_platform_role(array[''SUPER_ADMIN'',''MATRICIA_ADMIN'',''READ_ONLY_AUDITOR''])'when t in('brand_kits','marketing_consents','social_connections','marketing_campaigns','marketing_exceptions','social_publication_jobs','marketing_attribution_events','marketing_metric_events')then'private.marketing_manage_access(organization_id) or private.has_platform_role(array[''READ_ONLY_AUDITOR''])'else case t when'brand_kit_versions'then'exists(select 1 from public.brand_kits k where k.id=brand_kit_id)'when'marketing_content'then'exists(select 1 from public.marketing_campaigns c where c.id=campaign_id)'when'marketing_content_versions'then'exists(select 1 from public.marketing_content c join public.marketing_campaigns m on m.id=c.campaign_id where c.id=content_id)'when'marketing_content_sources'then'exists(select 1 from public.marketing_content_versions v join public.marketing_content c on c.id=v.content_id join public.marketing_campaigns m on m.id=c.campaign_id where v.id=content_version_id)'when'marketing_calendar_items'then'exists(select 1 from public.marketing_campaigns c where c.id=campaign_id)'when'social_publication_results'then'exists(select 1 from public.social_publication_jobs j where j.id=job_id)'end end);end loop;end$$;
grant select on public.marketing_consents,public.brand_kits,public.brand_kit_versions,public.marketing_templates,public.marketing_template_versions,public.social_connections,public.marketing_campaigns,public.marketing_content,public.marketing_content_versions,public.marketing_content_sources,public.marketing_calendar_items,public.marketing_exceptions,public.social_publication_jobs,public.social_publication_results,public.marketing_attribution_events,public.marketing_metric_events,public.marketing_campaign_performance to authenticated;
create trigger marketing_consents_immutable before update or delete on public.marketing_consents for each row execute function private.prevent_marketing_history_change();create trigger brand_versions_immutable before update or delete on public.brand_kit_versions for each row execute function private.prevent_marketing_history_change();create trigger template_versions_immutable before update or delete on public.marketing_template_versions for each row execute function private.prevent_marketing_history_change();create trigger content_sources_immutable before update or delete on public.marketing_content_sources for each row execute function private.prevent_marketing_history_change();create trigger publication_results_immutable before update or delete on public.social_publication_results for each row execute function private.prevent_marketing_history_change();create trigger attribution_events_immutable before update or delete on public.marketing_attribution_events for each row execute function private.prevent_marketing_history_change();create trigger metric_events_immutable before update or delete on public.marketing_metric_events for each row execute function private.prevent_marketing_history_change();
revoke all on function private.marketing_manage_access(uuid,uuid),private.marketing_consent_active(uuid,text),private.prevent_marketing_history_change(),public.record_marketing_consent(uuid,text,text,text,text,text,uuid),public.create_marketing_campaign(uuid,uuid,text,text,text,integer,integer,jsonb,jsonb,text,uuid),public.approve_marketing_campaign(uuid,integer,text,uuid),public.schedule_marketing_campaign(uuid,jsonb,integer,text,uuid),public.record_marketing_metric(uuid,text,bigint,bigint,text,text,timestamptz,text,uuid)from public,anon,authenticated,service_role;grant execute on function private.marketing_manage_access(uuid,uuid),private.marketing_consent_active(uuid,text)to authenticated;grant execute on function public.record_marketing_consent(uuid,text,text,text,text,text,uuid),public.create_marketing_campaign(uuid,uuid,text,text,text,integer,integer,jsonb,jsonb,text,uuid),public.approve_marketing_campaign(uuid,integer,text,uuid),public.schedule_marketing_campaign(uuid,jsonb,integer,text,uuid),public.record_marketing_metric(uuid,text,bigint,bigint,text,text,timestamptz,text,uuid)to authenticated;
create index marketing_consents_current_idx on public.marketing_consents(organization_id,purpose,decided_at desc,id desc);create index campaigns_org_status_idx on public.marketing_campaigns(organization_id,status,created_at desc);create index content_campaign_idx on public.marketing_content(campaign_id);create index content_versions_status_idx on public.marketing_content_versions(status,risk_score,expires_at);create index calendar_schedule_idx on public.marketing_calendar_items(status,scheduled_at);create index publication_jobs_queue_idx on public.social_publication_jobs(status,available_at);create index attribution_campaign_time_idx on public.marketing_attribution_events(campaign_id,occurred_at);create index metrics_campaign_time_idx on public.marketing_metric_events(campaign_id,occurred_at);
notify pgrst,'reload schema';
